-- Seeds one official community post per app recipe (author_id = null,
-- displayed as "Tarifim Mutfağı" in the UI) so the Topluluk feed always
-- has real content instead of starting empty. Safe to re-run: the
-- (recipe_id) partial unique index on posts makes every insert idempotent.
-- Run this once in the SQL Editor, after schema.sql.

on conflict (recipe_id) where recipe_id is not null do nothing;
